    tmpIn1.x = xi;
    tmpIn1.y = yi + 1.0;
    tmpIn2.x = sin(tmpIn1.x * tmpIn1.x);
    tmpIn2.y = cos(tmpIn1.y * tmpIn1.y);
    vec2  vec_grad01 = vec2(rand(tmpIn1)-0.5,rand(tmpIn2)-0.5);

    tmpIn1.x = xi + 1.0;
    tmpIn1.y = yi + 1.0;
    tmpIn2.x = sin(tmpIn1.x * tmpIn1.x);
    tmpIn2.y = cos(tmpIn1.y * tmpIn1.y);
    vec2  vec_grad11 = vec2(rand(tmpIn1)-0.5,rand(tmpIn2)-0.5);

    vec2 vec_dist00 = vec2(xf,yf);
    vec2 vec_dist10 = vec2(-(1.0-xf),yf);
    vec2 vec_dist01 = vec2(xf,-(1.0-yf));
    vec2 vec_dist11 = vec2(-(1.0-xf),-(1.0-yf));

    float dot00 = dot(vec_grad00,vec_dist00);
    float dot10 = dot(vec_grad10,vec_dist10);
    float dot01 = dot(vec_grad01,vec_dist01);
    float dot11 = dot(vec_grad11,vec_dist11);

    float ux = fade(xf)*1.0;
    float uy = fade(yf)*1.0;

    float ave_dot0010 = lerpF(dot00,dot10,ux);
    float ave_dot0111 = lerpF(dot01,dot11,ux);

    //float ave = (lerpF(ave_dot0010,ave_dot0111,uy)+1.0)/2.0;
    return (lerpF(ave_dot0010,ave_dot0111,uy)+1.0)/2.0;

  }
  float valuenoise2D(float x,float y){
    vec2 I = vec2(floor(x)*1.0,floor(y)*1.0);
    vec2 F = vec2(x-I.x,y-I.y);

    float a = rand(I);
    float b = rand(vec2(I.x+1.0,I.y));
    float c = rand(vec2(I.x,I.y+1.0));
    float d = rand(vec2(I.x+1.0,I.y+1.0));

    float u = fade(F.x);
    float v = fade(F.y);

    float Vab = (1.0-u)*a + u*b;
    float Vcd = (1.0-u)*c + u*d;

    float Vp  = (1.0-v)*Vab+v*Vcd;

    return Vp;//mix(a, b, u) + (c - a)* v * (1.0 - u) + (d - b) * u * v;

  }
  float fbm(vec3 p){
    float sum = 0.0;
    float freq = 1.0;
    float amp = 1.0;
    float max = 0.0;
    float falloff = 0.5;
    for(float i = 0.0; i < 4.0; i++){
      sum += perlin3D(p.x*freq, p.y*freq, p.z*freq)*amp;
      max += amp;
      amp *= falloff;
      freq *= 2.0;
    }
    return sum;///max;
  }
  float fbm2D(vec2 p){
    float sum = 0.0;
    float freq = 1.0;
    float amp = 1.0;
    float max = 0.0;
    float falloff = 0.5;
    for(float i = 0.0; i < 5.0; i++){
      //sum += perlin2D(p.x*freq, p.y*freq)*amp;
      sum += valuenoise2D(p.x*freq, p.y*freq)*amp;
      max += amp;
      amp *= falloff;
      freq *= 2.0;
    }
    return sum/max;
  }
  void main() {
    float r = 0.0;
    float g = resolution.y;
    float b = resolution.y;
    vec4 TexPixel = texture2D(TCTexture, vTexCoord);

